import bisect

class TimeMap:
    def __init__(self):
        self.store = {}

    def set(self, key, value, timestamp):
        self.store.setdefault(key, []).append((timestamp, value))   # already sorted, appended in order

    def get(self, key, timestamp):
        entries = self.store.get(key, [])
        idx = bisect.bisect_right(entries, (timestamp, chr(0x10FFFF)))   # first entry after timestamp
        if idx == 0:
            return ''
        return entries[idx - 1][1]

