import java.util.*;

public class TimeMap {
    Map<String, List<int[]>> timestamps = new HashMap<>();
    Map<String, List<String>> values = new HashMap<>();

    void set(String key, String value, int timestamp) {
        timestamps.computeIfAbsent(key, k -> new ArrayList<>()).add(new int[]{timestamp});
        values.computeIfAbsent(key, k -> new ArrayList<>()).add(value);   // already sorted, appended in order
    }

    String get(String key, int timestamp) {
        List<int[]> ts = timestamps.getOrDefault(key, new ArrayList<>());
        int lo = 0, hi = ts.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ts.get(mid)[0] <= timestamp) lo = mid + 1; else hi = mid;   // binary search the boundary
        }
        return lo == 0 ? "" : values.get(key).get(lo - 1);
    }
}

