    unordered_map<string, vector<pair<int,string>>> store;

    void set(string key, string value, int timestamp) {
        store[key].push_back({timestamp, value});     // already sorted, appended in order
    }

    string get(string key, int timestamp) {
        auto& entries = store[key];
        int lo = 0, hi = entries.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (entries[mid].first <= timestamp) lo = mid + 1; else hi = mid;   // binary search the boundary
        }
        return lo == 0 ? "" : entries[lo - 1].second;
    }
};
